'use client'

import { useEffect, useRef, useState } from 'react'
import { ArrowRight, BarChart3, BrainCircuit, Building2, Check, ChevronRight, CircleDot, ClipboardCheck, FileCheck2, FileText, FolderSearch, Gauge, GitBranch, LayoutDashboard, Menu, Network, Paperclip, Play, Plus, Radar, ShieldCheck, Sparkles, UploadCloud, X, Zap } from 'lucide-react'

type View = 'welcome' | 'profile' | 'dashboard' | 'analysis' | 'evidence' | 'agents' | 'report'
type Profile = Record<string, string>
const nav = [{ id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard }, { id: 'profile', label: 'Company Profile', icon: Building2 }, { id: 'analysis', label: 'Tender Analysis', icon: Radar }, { id: 'evidence', label: 'Evidence', icon: FolderSearch }, { id: 'report', label: 'Reports', icon: FileText }] as const
const pipeline = ['Upload tender', 'Retrieve evidence', 'Analyze requirements', 'Recommend action']
const analysisSteps = ['Document Processing', 'Text Extraction', 'Hybrid Retrieval', 'Eligibility Analysis', 'Compliance Analysis', 'Risk Analysis', 'Recommendation']
const agents = [['Document Reader Agent', 'Extracts structure, tables, and clauses', FileText], ['Eligibility Agent', 'Maps requirements to company profile', ClipboardCheck], ['Compliance Agent', 'Checks documents and evidence', ShieldCheck], ['Risk Analysis Agent', 'Surfaces contractual and delivery risks', Gauge], ['Proposal Generation Agent', 'Prepares response-ready insights', Sparkles], ['Recommendation Agent', 'Synthesizes a grounded bid decision', BrainCircuit]] as const

function Logo({ inverse = false }: { inverse?: boolean }) { return <div className="flex items-center gap-3"><div className={`grid size-9 place-items-center rounded-xl shadow-sm ${inverse ? 'bg-white text-primary' : 'bg-primary text-primary-foreground'}`}><GitBranch className="size-5" /></div><div><div className={`font-semibold tracking-tight ${inverse ? 'text-white' : 'text-foreground'}`}>TenderForge</div><div className={`text-[10px] uppercase tracking-[0.18em] ${inverse ? 'text-white/65' : 'text-muted-foreground'}`}>Tender intelligence</div></div></div> }
function Empty({ label, className = '' }: { label: string; className?: string }) { return <div className={`flex min-h-24 items-center justify-center rounded-xl border border-dashed border-border bg-muted/30 px-4 text-center text-sm text-muted-foreground ${className}`}>{label}</div> }
function Header({ eyebrow, title, desc }: { eyebrow: string; title: string; desc: string }) { return <div className="mb-8"><p className="text-xs font-semibold uppercase tracking-[0.16em] text-primary">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-balance">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{desc}</p></div> }

export default function Page() {
  const [view, setView] = useState<View>('welcome'); const [profile, setProfile] = useState<Profile>({}); const [file, setFile] = useState<File | null>(null); const [analyzing, setAnalyzing] = useState(false); const [step, setStep] = useState(-1); const [registered, setRegistered] = useState(false); const [presentation, setPresentation] = useState(false); const inputRef = useRef<HTMLInputElement>(null)
  useEffect(() => { if (!analyzing) return; setStep(0); const timer = window.setInterval(() => setStep((s) => Math.min(s + 1, analysisSteps.length - 1)), 800); return () => window.clearInterval(timer) }, [analyzing])
  useEffect(() => { if (analyzing && step === analysisSteps.length - 1) { const done = window.setTimeout(() => { setAnalyzing(false); setView('analysis') }, 1000); return () => window.clearTimeout(done) } }, [analyzing, step])
  const update = (key: string, value: string) => setProfile((p) => ({ ...p, [key]: value })); const start = () => { if (file) { setAnalyzing(true); setView('analysis') } }
  if (view === 'welcome') return <Welcome registered={registered} onRegister={() => setRegistered(true)} onEnter={() => setView('profile')} />
  const current = nav.find((n) => n.id === view)
  return <div className="min-h-screen bg-muted/20"><header className="sticky top-0 z-10 border-b border-primary/30 bg-[#12355B] shadow-sm"><div className="mx-auto flex h-16 max-w-[1500px] items-center justify-between px-5 lg:px-8"><Logo inverse /><nav className="hidden items-center gap-1 lg:flex">{nav.map((item) => <button key={item.id} onClick={() => setView(item.id)} className={`flex items-center gap-2 rounded-lg px-3 py-2 text-sm transition ${view === item.id ? 'bg-white/15 font-semibold text-white' : 'text-white/75 hover:bg-white/10 hover:text-white'}`}><item.icon className="size-4" />{item.label}</button>)}</nav><div className="flex items-center gap-3"><button onClick={() => setPresentation(!presentation)} className="hidden rounded-lg border border-white/20 px-3 py-2 text-xs text-white/85 sm:block">{presentation ? 'Exit presentation' : 'Presentation mode'}</button><button className="grid size-9 place-items-center rounded-lg border border-white/20 text-white lg:hidden"><Menu className="size-4" /></button><button onClick={() => setView('welcome')} className="grid size-9 place-items-center rounded-full bg-white/15 text-sm font-semibold text-white" aria-label="Log out">TF</button></div></div></header><main className="mx-auto max-w-[1500px] px-5 py-8 lg:px-8">{current && <div className="mb-5 flex items-center gap-2 text-xs text-muted-foreground"><span>Workspace</span><ChevronRight className="size-3" /><span className="font-medium text-foreground">{current.label}</span></div>}{view === 'profile' ? <ProfileView profile={profile} update={update} onSave={() => setView('dashboard')} /> : view === 'dashboard' ? <Dashboard file={file} setFile={setFile} inputRef={inputRef} onAnalyze={start} onNavigate={setView} /> : view === 'analysis' && analyzing ? <Progress step={step} file={file} /> : view === 'analysis' ? <Analysis onEvidence={() => setView('evidence')} onReport={() => setView('report')} /> : view === 'evidence' ? <Evidence /> : view === 'agents' ? <Agents step={step} /> : <Report onBack={() => setView('analysis')} />}</main><footer className="mx-auto flex max-w-[1500px] items-center justify-between px-5 pb-8 text-xs text-muted-foreground lg:px-8"><span>© 2026 TenderForge</span><span>Grounded in evidence. Built for confident procurement.</span></footer></div>
}

function Welcome({ registered, onRegister, onEnter }: { registered: boolean; onRegister: () => void; onEnter: () => void }) { return <main className="min-h-screen bg-grid"><div className="mx-auto flex min-h-screen max-w-6xl items-center justify-center px-6 py-16"><div className="grid w-full max-w-5xl items-center gap-16 lg:grid-cols-[1fr_0.8fr]"><div><Logo /><div className="mt-20 max-w-xl"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-primary/15 bg-primary/5 px-3 py-1.5 text-xs font-medium text-primary"><Sparkles className="size-3.5" /> Multi-agent cognitive RAG</div><h1 className="text-balance text-5xl font-semibold tracking-[-0.04em] sm:text-6xl">Turn complex tenders into <span className="text-primary">clear decisions.</span></h1><p className="mt-6 max-w-lg text-lg leading-8 text-muted-foreground">TenderForge brings retrieval, multi-agent reasoning, and evidence together for confident tender intelligence.</p><button onClick={onEnter} className="mt-9 inline-flex items-center gap-3 rounded-xl bg-primary px-5 py-3.5 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/15 transition hover:-translate-y-0.5">Enter Dashboard <ArrowRight className="size-4" /></button></div><div className="mt-20 flex gap-6 text-xs text-muted-foreground"><span className="flex items-center gap-2"><ShieldCheck className="size-4 text-accent" /> Grounded in evidence</span><span className="flex items-center gap-2"><Zap className="size-4 text-accent" /> Built for procurement teams</span></div></div><div className="rounded-3xl border border-border bg-card/85 p-5 shadow-2xl shadow-primary/5 backdrop-blur"><div className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="flex items-center justify-between"><span className="text-sm font-medium opacity-80">Tender intelligence engine</span><CircleDot className="size-4 text-accent" /></div><div className="mt-14 text-3xl font-semibold">One workflow.<br />Every decision grounded.</div></div><div className="grid gap-3 p-3 pt-6">{['Upload a tender', 'Retrieve evidence', 'Assess eligibility', 'Recommend next steps'].map((x, i) => <div key={x} className="flex items-center gap-3 rounded-xl border border-border p-3 text-sm"><span className="grid size-7 place-items-center rounded-full bg-accent/15 text-xs font-semibold text-accent-foreground">{i + 1}</span>{x}<Check className="ml-auto size-4 text-accent" /></div>)}</div><button onClick={onRegister} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-border py-3 text-sm font-medium hover:bg-muted">{registered ? 'Workspace ready' : 'Create demo workspace'} <Plus className="size-4" /></button></div></div></div></main> }

function ProfileView({ profile, update, onSave }: { profile: Profile; update: (k: string, v: string) => void; onSave: () => void }) { const fields = [['company', 'Company Name', 'Enter company name'], ['industry', 'Industry', 'e.g. Infrastructure, IT services'], ['experience', 'Years of Experience', 'Enter years'], ['turnover', 'Annual Turnover', 'Enter annual turnover'], ['certifications', 'Certifications', 'Add certification'], ['expertise', 'Technical Expertise', 'Describe your expertise'], ['projects', 'Previous Projects', 'Add previous project'], ['employees', 'Employee Strength', 'Enter employee count']]; return <div className="mx-auto max-w-4xl"><Header eyebrow="Workspace setup" title="Build your company context" desc="TenderForge uses this profile to ground eligibility and compliance analysis. Keep it editable as your capabilities evolve." /><div className="rounded-2xl border border-border bg-card p-6 shadow-sm sm:p-8"><div className="grid gap-5 sm:grid-cols-2">{fields.map(([key, label, placeholder]) => <label key={key} className="flex flex-col gap-2 text-sm font-medium"><span>{label}</span>{['expertise', 'projects'].includes(key) ? <textarea value={profile[key] ?? ''} onChange={(e) => update(key, e.target.value)} placeholder={placeholder} className="min-h-28 resize-y rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /> : <input value={profile[key] ?? ''} onChange={(e) => update(key, e.target.value)} placeholder={placeholder} className="h-11 rounded-xl border border-input bg-background px-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" />}</label>)}</div><div className="mt-8 flex justify-end"><button onClick={onSave} className="inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground">Save profile <Check className="size-4" /></button></div></div></div> }

function Dashboard({ file, setFile, inputRef, onAnalyze, onNavigate }: { file: File | null; setFile: (f: File | null) => void; inputRef: React.RefObject<HTMLInputElement | null>; onAnalyze: () => void; onNavigate: (v: View) => void }) { return <><Header eyebrow="Tender intelligence workspace" title="Good morning. Ready to analyze?" desc="Upload a tender document to begin a grounded, multi-agent review. No results are generated until you provide a source document." /><div className="mb-8 grid gap-3 md:grid-cols-4">{pipeline.map((label, i) => <div key={label} className="flex items-center gap-3 rounded-xl border border-border bg-card p-3 text-sm"><span className="grid size-7 place-items-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">{i + 1}</span><span className={i === 0 ? 'font-semibold' : 'text-muted-foreground'}>{label}</span>{i < 3 && <ChevronRight className="ml-auto size-4 text-muted-foreground" />}</div>)}</div><div className="grid gap-6 xl:grid-cols-[1.45fr_0.8fr]"><section className="rounded-2xl border border-border bg-card p-6 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Upload Tender / RFP</h2><p className="mt-1 text-sm text-muted-foreground">PDF or DOCX · Your document stays in this demo workspace</p></div><UploadCloud className="size-5 text-accent" /></div><div onDragOver={(e) => e.preventDefault()} onDrop={(e) => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f) setFile(f) }} onClick={() => inputRef.current?.click()} className="mt-6 flex min-h-64 cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-primary/20 bg-primary/[0.025] px-6 text-center hover:border-primary/50"><input ref={inputRef} type="file" accept=".pdf,.docx" className="hidden" onChange={(e) => e.target.files?.[0] && setFile(e.target.files[0])} />{file ? <><div className="grid size-14 place-items-center rounded-2xl bg-accent/10 text-accent"><FileCheck2 className="size-7" /></div><p className="mt-4 font-medium">{file.name}</p><p className="mt-1 text-sm text-muted-foreground">Ready for analysis · Click to replace</p></> : <><div className="grid size-14 place-items-center rounded-2xl bg-primary/10 text-primary"><UploadCloud className="size-7" /></div><p className="mt-4 font-medium">Drop your tender here</p><p className="mt-1 text-sm text-muted-foreground">or click to browse your files</p></>}</div>{file && <div className="mt-4 flex items-center justify-between rounded-xl bg-muted p-3 text-sm"><span className="flex items-center gap-2"><Paperclip className="size-4 text-primary" />{file.name}</span><button onClick={(e) => { e.stopPropagation(); setFile(null) }} aria-label="Remove file"><X className="size-4 text-muted-foreground" /></button></div>}<button disabled={!file} onClick={onAnalyze} className="mt-5 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3.5 text-sm font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-40"><Play className="size-4" /> Analyze tender</button></section><aside className="flex flex-col gap-4"><Mini title="Company Profile" icon={Building2} onClick={() => onNavigate('profile')} /><Mini title="Agent workflow" icon={Network} onClick={() => onNavigate('agents')} /><Mini title="Evidence & RAG" icon={FolderSearch} onClick={() => onNavigate('evidence')} /><div className="rounded-2xl border border-primary/15 bg-primary/[0.04] p-5"><div className="flex items-center gap-3"><BarChart3 className="size-5 text-primary" /><p className="font-semibold">Results stay grounded</p></div><p className="mt-3 text-sm leading-6 text-muted-foreground">TenderForge will never invent eligibility, compliance, or risk results without an uploaded source.</p></div></aside></div></> }
function Mini({ title, icon: Icon, onClick }: { title: string; icon: typeof FileText; onClick: () => void }) { return <button onClick={onClick} className="flex items-center gap-3 rounded-xl border border-border bg-card p-4 text-left text-sm font-medium shadow-sm hover:-translate-y-0.5 hover:border-primary/30"><span className="grid size-9 place-items-center rounded-lg bg-muted text-primary"><Icon className="size-4" /></span>{title}<ChevronRight className="ml-auto size-4 text-muted-foreground" /></button> }
function Progress({ step, file }: { step: number; file: File | null }) { return <div className="mx-auto max-w-3xl"><Header eyebrow="Live analysis" title="TenderForge is reading your document" desc={file ? `Processing ${file.name}. Each stage is grounded in the uploaded source.` : 'Processing your uploaded tender document.'} /><div className="rounded-2xl border border-border bg-card p-6 shadow-sm sm:p-8"><div className="mb-8 flex items-center justify-between rounded-xl bg-primary/[0.04] p-4"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-primary text-primary-foreground"><BrainCircuit className="size-5 animate-pulse" /></div><div><p className="text-sm font-semibold">Cognitive RAG pipeline</p><p className="text-xs text-muted-foreground">No conclusions until evidence is retrieved</p></div></div><span className="text-sm font-semibold text-primary">{Math.max(0, Math.round(((step + 1) / analysisSteps.length) * 100))}%</span></div><div className="flex flex-col gap-1">{analysisSteps.map((name, i) => <div key={name} className="flex items-center gap-4 rounded-xl p-3"><div className={`grid size-8 place-items-center rounded-full border ${i < step ? 'border-accent bg-accent text-accent-foreground' : i === step ? 'border-primary bg-primary text-primary-foreground' : 'border-border text-muted-foreground'}`}>{i < step ? <Check className="size-4" /> : i === step ? <Zap className="size-4 animate-pulse" /> : <span className="text-xs">{i + 1}</span>}</div><span className={`text-sm ${i <= step ? 'font-semibold' : 'text-muted-foreground'}`}>{name}</span><span className="ml-auto text-xs text-muted-foreground">{i < step ? 'Completed' : i === step ? 'Analyzing…' : 'Waiting'}</span></div>)}</div></div></div> }
function Panel({ title, icon: Icon, children }: { title: string; icon: typeof FileText; children: React.ReactNode }) { return <section className="rounded-2xl border border-border bg-card p-6"><div className="mb-5 flex items-center gap-3"><Icon className="size-5 text-primary" /><h2 className="font-semibold">{title}</h2></div>{children}</section> }
function Analysis({ onEvidence, onReport }: { onEvidence: () => void; onReport: () => void }) { return <><Header eyebrow="Tender analysis" title="Tender intelligence" desc="Structured results will populate from the uploaded tender and your company profile. Empty fields are intentional until evidence is available." /><div className="mb-6 flex flex-wrap gap-3"><button onClick={onEvidence} className="rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-medium">Open evidence view</button><button onClick={onReport} className="rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground">Preview report</button></div><div className="grid gap-6 xl:grid-cols-[0.9fr_1.1fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center gap-3"><FileText className="size-5 text-primary" /><h2 className="font-semibold">Tender Information</h2></div><div className="mt-6 flex flex-col gap-5">{['Tender title', 'Submission deadline', 'Project scope', 'Required qualifications', 'Required certifications', 'Financial criteria'].map((x) => <div key={x}><p className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">{x}</p><Empty label="Awaiting extracted tender data" /></div>)}</div></section><div className="flex flex-col gap-6"><Panel title="Eligibility" icon={ClipboardCheck}><Empty label="Eligibility requirements will appear after analysis" /></Panel><Panel title="Compliance" icon={ShieldCheck}><Empty label="Compliance checks are waiting for source data" /></Panel><Panel title="Risk Analysis" icon={Gauge}><div className="grid gap-2 sm:grid-cols-4">{['Contractual Risk', 'Financial Risk', 'Technical Risk', 'Deadline Risk'].map((x) => <div className="rounded-xl bg-muted/60 p-3" key={x}><p className="text-xs font-medium">{x}</p><p className="mt-3 text-xs text-muted-foreground">No data</p></div>)}</div></Panel></div></div></> }
function Evidence() { return <><Header eyebrow="Grounded reasoning" title="Evidence & RAG view" desc="Trace each future insight back to the tender clause that supports it. This view stays empty until a source document is available." /><div className="grid gap-6 lg:grid-cols-[0.8fr_1.2fr]"><section className="rounded-2xl border border-border bg-card p-6"><h2 className="font-semibold">User Question / Analysis Task</h2><Empty label="Your analysis task will appear here" className="mt-4 min-h-32" /><div className="mt-6 flex items-center gap-2 rounded-xl bg-accent/10 px-4 py-3 text-sm font-medium text-accent-foreground"><ShieldCheck className="size-4 text-accent" /> Grounded in uploaded tender document</div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><h2 className="font-semibold">Retrieved Tender Evidence</h2><span className="rounded-full bg-muted px-2.5 py-1 text-[11px] text-muted-foreground">0 sources</span></div><div className="mt-6 flex flex-col gap-5"><div><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Source Page</p><Empty label="Tender Page __" className="mt-2" /></div><div><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Relevant Clause</p><Empty label="Matched requirement will appear here" className="mt-2 min-h-28" /></div><div><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">AI Explanation</p><Empty label="Reasoning will cite retrieved evidence" className="mt-2 min-h-28" /></div></div></section></div></> }
function Agents({ step }: { step: number }) { return <><Header eyebrow="Orchestration" title="Multi-agent workflow" desc="Specialized agents collaborate in sequence. Their outputs remain grounded in the uploaded tender and company profile." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{agents.map(([name, responsibility, Icon], i) => { const status = step > i ? 'Completed' : step === i ? 'Running' : 'Waiting'; const tone = step > i ? 'bg-accent/15 text-accent-foreground' : step === i ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground'; return <div key={name} className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div className="grid size-11 place-items-center rounded-xl bg-primary/8 text-primary"><Icon className="size-5" /></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-medium ${tone}`}>{status}</span></div><h2 className="mt-5 font-semibold">{name}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{responsibility}</p><div className="mt-5 h-1.5 rounded-full bg-muted"><div className={`h-full rounded-full bg-primary transition-all duration-700 ${step > i ? 'w-full' : step === i ? 'w-2/3' : 'w-0'}`} /></div></div> })}</div></> }
function Report({ onBack }: { onBack: () => void }) { const sections = ['Tender Summary', 'Eligibility Summary', 'Compliance Summary', 'Risk Summary', 'Missing Requirements', 'Key Deadlines', 'Recommendation', 'Supporting Evidence']; return <><div className="flex flex-wrap items-start justify-between gap-4"><Header eyebrow="Report preview" title="Tender analysis report" desc="A presentation-ready report will be assembled from the completed analysis and cited evidence." /><button className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-medium"><FileText className="size-4" /> Download Report</button></div><div className="rounded-2xl border border-border bg-card p-6 shadow-sm sm:p-8"><div className="flex items-center justify-between border-b border-border pb-5"><div><p className="text-xs font-semibold uppercase tracking-wider text-primary">TenderForge report</p><h2 className="mt-2 text-xl font-semibold">Grounded tender intelligence</h2></div><span className="rounded-full bg-muted px-3 py-1 text-xs text-muted-foreground">Draft preview</span></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{sections.map((s) => <div key={s} className="flex items-center gap-3 rounded-xl border border-dashed border-border bg-muted/20 p-4 text-sm"><FileText className="size-4 text-primary" />{s}<span className="ml-auto text-xs text-muted-foreground">Awaiting data</span></div>)}</div><button onClick={onBack} className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-primary">Back to analysis <ArrowRight className="size-4" /></button></div></> }
